				Promise.resolve(
					commitFor(
						target,
						authorSequence,
						sourceOperations("singleton")[0]?.operation ?? Object.freeze({ action: "add", value: 1 }),
						7
					)
				)
			);
			activeHandle.deactivate();
			activeHandleNeedsDeactivate = false;
